package in.agricred.authservice;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.util.*; import javax.crypto.SecretKey;
@RestController @RequestMapping("/api/auth") @CrossOrigin(origins="*") public class AuthController { private final UserRepository users; private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder(); private final String secret=System.getenv().getOrDefault("JWT_SECRET","replace-this-with-a-random-secret-at-least-32-characters"); public AuthController(UserRepository users){this.users=users;}
record Register(String name,String email,String password,String role){} record Login(String email,String password){}
@PostMapping("/register") public ResponseEntity<?> register(@RequestBody Register r){ if(r.name()==null||r.email()==null||r.password()==null||r.password().length()<8) return ResponseEntity.badRequest().body(Map.of("error","Name, email and password (8+ chars) are required")); String role="BANKER".equalsIgnoreCase(r.role())?"BANKER":"FARMER"; if(users.existsByEmailIgnoreCase(r.email())) return ResponseEntity.status(409).body(Map.of("error","Email already registered")); UserAccount u=new UserAccount();u.name=r.name().trim();u.email=r.email().trim().toLowerCase();u.passwordHash=encoder.encode(r.password());u.role=role;users.save(u);return ResponseEntity.ok(token(u)); }
@PostMapping("/login") public ResponseEntity<?> login(@RequestBody Login r){UserAccount u=users.findByEmailIgnoreCase(r.email()==null?"":r.email()).orElse(null);if(u==null||!encoder.matches(r.password()==null?"":r.password(),u.passwordHash))return ResponseEntity.status(401).body(Map.of("error","Invalid email or password"));return ResponseEntity.ok(token(u));}
private Map<String,Object> token(UserAccount u){SecretKey key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));String jwt=Jwts.builder().subject(u.email).claim("role",u.role).claim("name",u.name).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+86400000L)).signWith(key).compact();return Map.of("token",jwt,"name",u.name,"email",u.email,"role",u.role,"userId",u.id);}
@GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP","service","auth-service");}}
